import json
import re
from pathlib import Path


sources = json.loads(Path('source.json').read_text())
references = json.loads(Path('reference-targets.json').read_text())
answers = []
for source in sources:
    answer = {key: source[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    answer.update(proposed_xml=None, reason='', review_notes='', status='retained_unchanged', classification='retained_necessary')
    answers.append(answer)


def impact(classification, assessment, limitations, burdens, effects=None):
    return dict(version=1, classification=classification, assessment=assessment,
                scope_limitations=limitations, new_burdens_review=burdens, effects=effects or [])


def effect(kind, measure_id, description, before, after, unit, population, transition,
           replacement, source_quote, proposed_quote):
    return dict(kind=kind, measure_id=measure_id, description=description, before=before,
                after=after, unit=unit, affected_population=population,
                conditions_and_transition=transition, replacement_or_new_burdens=replacement,
                source_quote=source_quote, proposed_quote=proposed_quote)


# Les paragraphes sans réforme restent ceux de la source officielle.
parts = re.findall(r'<p>.*?</p>', sources[0]['source_xml'], flags=re.S)
parts[3] = """<p>3. Le contribuable justifie, à la demande de l'administration, du respect des dispositions définies à l'article D. 319-16 du code de la construction et de l'habitation au moyen des seules pièces ordinaires de l'opération nécessaires à cette vérification. La production cumulative de devis et de factures n'est pas exigée lorsque l'un de ces documents ou les autres pièces ordinaires suffisent à établir les mêmes éléments. La date d'acceptation d'un devis, le versement d'un acompte et le paiement sont établis, lorsqu'ils sont nécessaires à l'application du 1 ou du champ temporel du dispositif, à partir des pièces ordinaires qui les constatent. Des diagnostics de performance énergétique au sens de l'article L. 126-26 du même code établissent que le bien objet des dépenses mentionnées au 1 respecte un niveau de performance énergétique au sens de l'article L. 173-1-1 du même code correspondant aux classes :</p>"""
parts[5] = parts[5].replace('31 décembre 2025', '31 décembre 2027')
parts.extend([
    """<p>Dans le champ initial de l'article 2 du décret n° 2023-297 du 21 avril 2023, ces dispositions s'appliquent aux dépenses de rénovation énergétique pour lesquelles le contribuable justifie de l'acceptation d'un devis intervenue à compter du 5 novembre 2022 et qui sont payées entre le 1er janvier 2023 et le 31 décembre 2025. Ces bornes historiques de paiement ne font pas obstacle au rehaussement pour les dépenses auxquelles le quatrième alinéa du 3° du I de l'article 156 du code général des impôts l'étend légalement, dans les conditions de fond et le champ temporel qui leur sont applicables. Le nouveau classement est justifié au plus tard le 31 décembre 2027 dans le champ de ce quatrième alinéa.</p>""",
    """<p>Le contribuable ne produit pas de nouveau les pièces et informations exactes et pertinentes pour la période concernée déjà détenues par l'administration ou légalement accessibles à celle-ci dans l'exercice de ses compétences. L'administration les réutilise et ne demande au contribuable que les éléments manquants nécessaires à la vérification des conditions du présent article. Aucune attestation de remplacement n'est exigée. La validité des diagnostics reste appréciée aux dates prévues au 3, sans renouvellement exigé du seul fait de leur expiration ultérieure.</p>""",
    """<p>Les allègements de production des justificatifs s'appliquent aux demandes adressées à compter de l'entrée en vigueur de la loi, y compris lorsqu'elles portent sur des dépenses antérieures. Aucun dossier déjà déposé n'est à refaire. Les dépenses restant légalement soumises à des dispositions antérieures conservent leurs conditions de fond et leur champ temporel propres. Les déductions acquises, restitutions, prescriptions et voies de recours sont préservées ; aucun délai de réclamation expiré n'est rouvert.</p>""",
])
